import CascadeSelect from "@marko-ui/shadcn/ui/cascade-select/cascade-select.marko";

static const locations = [
  {
    value: "asia",
    label: "Asia",
    children: [
      {
        value: "india",
        label: "India",
        children: [
          { value: "mumbai", label: "Mumbai" },
          { value: "delhi", label: "Delhi" },
          { value: "bangalore", label: "Bangalore" },
        ],
      },
      {
        value: "japan",
        label: "Japan",
        children: [
          { value: "tokyo", label: "Tokyo" },
          { value: "osaka", label: "Osaka" },
        ],
      },
    ],
  },
  {
    value: "europe",
    label: "Europe",
    children: [
      {
        value: "france",
        label: "France",
        children: [
          { value: "paris", label: "Paris" },
          { value: "lyon", label: "Lyon" },
        ],
      },
      {
        value: "germany",
        label: "Germany",
        children: [
          { value: "berlin", label: "Berlin" },
          { value: "munich", label: "Munich" },
        ],
      },
    ],
  },
  {
    value: "north-america",
    label: "North America",
    disabled: true,
    children: [
      { value: "usa", label: "United States" },
      { value: "canada", label: "Canada" },
    ],
  },
];

<CascadeSelect items=locations placeholder="Select a city" label="Region / Country / City"/>

